from taf.sw.dcap.rd.schemas.base import SchemaField, SchemaObject


class GnbEnbProfileCMV1(SchemaObject):
    gnb_enb_id = SchemaField(name="id")
    name = SchemaField(name="name")
    tracers = SchemaField(name="tracers")

    def __init__(self, gnb_enb_id=None, name=None, tracers=None):
        self.gnb_enb_id = gnb_enb_id
        self.name = name
        self.tracers = tracers

        super(GnbEnbProfileCMV1, self).__init__()
